import unittest

from hourglass.gaps import find_gaps
from hourglass.parsing import parse_span


def spans(*texts):
    return [parse_span(text) for text in texts]


class FindGapsTest(unittest.TestCase):
    hours = parse_span("09:00-17:00")

    def test_middle_gap(self):
        got = find_gaps(
            spans("09:00-12:00", "13:00-17:00"), self.hours
        )
        self.assertEqual(["gap 12:00-13:00 (60 min)"], got)

    def test_edges_and_overlap(self):
        got = find_gaps(
            spans("10:00-11:00", "10:30-12:00"), self.hours
        )
        self.assertEqual(
            [
                "gap 09:00-10:00 (60 min)",
                "gap 12:00-17:00 (300 min)"
            ],
            got
        )

    def test_full_and_empty(self):
        full = spans("09:00-17:00")
        self.assertEqual([], find_gaps(full, self.hours))
        self.assertEqual(
            ["gap 09:00-17:00 (480 min)"],
            find_gaps([], self.hours)
        )

    def test_outside_hours_raises(self):
        with self.assertRaises(ValueError):
            find_gaps(spans("08:00-10:00"), self.hours)
        with self.assertRaises(ValueError):
            find_gaps(spans("16:00-18:00"), self.hours)


if __name__ == "__main__":
    unittest.main()
